const arrowDefs = `<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto-start-reverse"><path d="M0 0 8 4 0 8" fill="none" stroke="#8b9f8b" stroke-width="1.2"/></marker></defs>`;
function loopDiagram(id, labels, compact=false) {
  const w=compact?900:1440, nodeW=compact?145:240, gap=compact?35:48, y=compact?70:40, h=84;
  const nodes=labels.map((label,i)=>{const x=8+i*(nodeW+gap),cx=x+nodeW/2;const text=compact&&i===4?`<tspan x="${cx}" y="${y+34}">Improved</tspan><tspan x="${cx}" y="${y+60}">attempt</tspan>`:label;return `<g class="diagram-node" data-node="${i}"><rect x="${x}" y="${y}" width="${nodeW}" height="${h}" rx="8"/><text class="svg-label" x="${cx}" y="${y+49}" text-anchor="middle" style="font-size:${compact?20:25}px">${text}</text></g>`}).join('');
  const lines=labels.slice(1).map((_,i)=>{const x=8+i*(nodeW+gap)+nodeW;return `<path class="flow-line" data-edge="${i+1}" d="M${x+4} ${y+h/2}H${x+gap-9}" marker-end="url(#arrow-${id})"/><circle class="signal" data-signal="${i+1}" r="5" style="offset-path:path('M${x+2} ${y+h/2}H${x+gap-5}')"/>`}).join('');
  const endX=8+4*(nodeW+gap)+nodeW/2, planX=8+(compact?0:1)*(nodeW+gap)+nodeW/2;
  return `<svg id="${id}" class="${compact?'memory-loop':'loop-svg'}" viewBox="0 0 ${w} ${compact?290:255}" role="img" aria-label="${labels.join(' to ')}; feedback returns to ${compact?'the next attempt':'planning'}.">${arrowDefs.replace('id="arrow"',`id="arrow-${id}"`)}${lines}<path class="flow-line" data-edge="4" d="M${endX} ${y+h+4}V${y+h+65}H${planX}V${y+h+5}" marker-end="url(#arrow-${id})"/><text class="return-label" x="${(endX+planX)/2}" y="${y+h+99}" text-anchor="middle">${compact?'Store what worked. Reuse it when the task changes.':'Environmental feedback changes the next decision.'}</text>${nodes}</svg>`;
}
