function network(id){
  const roles=[{x:155,y:90,role:'Planner',task:'Break down the question'},{x:735,y:90,role:'Researcher',task:'Retrieve cited evidence'},{x:155,y:340,role:'Tool executor',task:'Run a reproducible test'},{x:735,y:340,role:'Reviewer',task:'Check methods & claims'}];
  return `<svg id="${id}" class="network-svg" viewBox="0 0 900 440" role="img" aria-label="A coordinator delegates to planner, researcher, tool executor and reviewer; artifacts return for a shared result.">${roles.map((r,i)=>`<path class="flow-line" data-edge="${i+1}" d="M450 215L${r.x} ${r.y}"/><circle class="signal" data-signal="${i+1}" r="6" style="offset-path:path('M450 215L${r.x} ${r.y}')"/>`).join('')}${roles.map((r,i)=>`<g class="diagram-node" data-node="${i+1}"><rect x="${r.x-128}" y="${r.y-42}" width="256" height="84" rx="7"/><text class="role" x="${r.x}" y="${r.y-1}" text-anchor="middle">${r.role}</text><text class="task" x="${r.x}" y="${r.y+27}" text-anchor="middle">${r.task}</text></g>`).join('')}<g class="diagram-node coord" data-node="0"><circle cx="450" cy="215" r="83"/><text class="role" x="450" y="210" text-anchor="middle">Coordinator</text><text x="450" y="240" text-anchor="middle" style="font-size:17px">Shared task state</text></g><text class="svg-caption" x="450" y="432" text-anchor="middle">Explicit roles + shared artifacts + a review gate</text></svg>`;
}
